package com.bare.messagescalls.schedule;
public final class DomainTaskPreparation {public enum Decision{READY,SKIPPED_NO_DATA,SKIPPED_PERMISSION,SKIPPED_DEVICE_ACCESS}public static Decision messages(boolean p,int n){return !p?Decision.SKIPPED_PERMISSION:(n>0?Decision.READY:Decision.SKIPPED_NO_DATA);}public static Decision calls(boolean p,int n){return !p?Decision.SKIPPED_PERMISSION:(n>0?Decision.READY:Decision.SKIPPED_NO_DATA);}public static Decision wifi(boolean a,int n){return !a?Decision.SKIPPED_DEVICE_ACCESS:(n>0?Decision.READY:Decision.SKIPPED_NO_DATA);}public static Decision folders(int n){return n>0?Decision.READY:Decision.SKIPPED_NO_DATA;}public static Decision wallpapers(int n){return n>0?Decision.READY:Decision.SKIPPED_NO_DATA;}}
